def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "buy_issuer_a": And([
            self.product_selected(self.issuer_a_product),
            self.combined_exposure() + 150 > self.issuer_a_cap(),
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
